import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search action
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field}, value={value}')"
    db.execute(log_query)
    db.commit()

    # Perform the actual search - field is validated above so safe to interpolate
    search_query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"
    try:
        results = db.execute(search_query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, password_hash, role, api_key) VALUES (?, ?, ?, ?, ?)',
            (data['username'], data.get('email', ''), password_hash, 'user', api_key)
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_users():
    """Admin endpoint - exports all user data including sensitive fields"""
    auth = request.headers.get('X-Admin-Key', '')
    expected = os.environ.get('ADMIN_KEY', 'changeme')
    if not hmac.compare_digest(auth, expected):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    results = db.execute('SELECT * FROM users').fetchall()
    users = [dict(row) for row in results]
    return jsonify({'users': users})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
